'use strict';
let midiAccess=null,midiInputPorts=[],midiOut=null,midiConnecting=false,midiExternal=false,midiLastClock=0,midiIntervals=[],midiNotes=new Map();
function midiConfig(){return state.midi||(state.midi=M.midi())}
function renderMidiBadge(){const input=midiAccess?[...midiAccess.inputs.values()].some(p=>p.state==='connected'):false,output=!!midiOut&&midiOut.state==='connected';$('#midiOpen').classList.toggle('connected',input||output);$('#midiOpen').textContent=input||output?'MIDI ●':'MIDI'}
function refreshMidiUI(){const c=midiConfig();for(const [id,key]of [['midiMode','mode'],['midiChannel','channel'],['midiOutChannel','outChannel']])$('#'+id).value=c[key];for(const [id,key]of [['midiNotesOut','notesOut'],['midiClockIn','clockIn'],['midiClockOut','clockOut']])$('#'+id).checked=c[key];if(midiAccess)refreshMidiPorts();renderMidiBadge()}
function refreshMidiPorts(){for(const port of midiInputPorts)port.onmidimessage=null;midiInputPorts=[...midiAccess.inputs.values()].filter(p=>p.state==='connected');for(const p of midiInputPorts)p.onmidimessage=handleStudioMIDI;const config=midiConfig();for(const [id,ports,none,selected]of [['midiInput',midiAccess.inputs,'Toutes les entrées',config.input],['midiOutput',midiAccess.outputs,'Aucune',config.output]]){const select=$('#'+id);select.replaceChildren();const first=document.createElement('option');first.value='';first.textContent=none;select.append(first);for(const p of ports.values()){const o=document.createElement('option');o.value=p.id;o.textContent=p.name||p.id;select.append(o)}select.value=selected}midiOut=midiAccess.outputs.get(config.output)||null;$('#midiStatus').textContent=midiInputPorts.length?midiInputPorts.map(p=>p.name||'Contrôleur').join(' · '):'Aucune entrée MIDI détectée.';renderMidiBadge()}
$('#midiOpen').onclick=()=>{refreshMidiUI();if(!navigator.requestMIDIAccess)$('#midiStatus').textContent='Web MIDI indisponible ici. La connexion d’un clavier devra être testée dans Chrome/Android compatible ou dans l’application native.';open('midiSheet')};$('#midiSheet .close').onclick=()=>$('#midiSheet').close();
$('#midiConnect').onclick=async()=>{if(midiConnecting)return;midiConnecting=true;$('#midiConnect').disabled=true;try{if(!navigator.requestMIDIAccess)throw Error('Web MIDI n’est pas pris en charge par ce navigateur.');midiAccess=await navigator.requestMIDIAccess({sysex:false});await unlock();refreshMidiPorts();midiAccess.onstatechange=()=>{midiPanic();for(const [token]of [...pressed])if(String(token).startsWith('midi:'))release(token);refreshMidiPorts()};$('#midiConnect').textContent='Actualiser la connexion'}catch(e){$('#midiStatus').textContent=e.message}finally{midiConnecting=false;$('#midiConnect').disabled=false}};
for(const [id,key,kind]of [['midiInput','input','string'],['midiOutput','output','string'],['midiMode','mode','string'],['midiChannel','channel','number'],['midiOutChannel','outChannel','number'],['midiNotesOut','notesOut','bool'],['midiClockIn','clockIn','bool'],['midiClockOut','clockOut','bool']])$('#'+id).onchange=()=>{midiPanic();for(const [token]of [...pressed])if(String(token).startsWith('midi:'))release(token);remember();const el=$('#'+id);midiConfig()[key]=kind==='bool'?el.checked:kind==='number'?+el.value:el.value;midiOut=midiAccess?.outputs.get(midiConfig().output)||null;midiLastClock=0;midiIntervals=[];changed();renderMidiBadge()};
function midiSend(bytes,time){if(!midiOut||midiOut.state==='disconnected')return;try{midiOut.send(bytes,time===undefined?undefined:performance.now()+Math.max(0,time-(audio.ctx?.currentTime||0))*1000)}catch(e){$('#midiStatus').textContent=e.message}}
function midiPanic(){try{midiOut?.clear()}catch{}for(const note of midiNotes.values())midiSend([128+note.channel,note.note,0]);midiNotes.clear();if(midiOut)for(let ch=0;ch<16;ch++)midiSend([176+ch,123,0])}
function midiStopPad(index){for(const [id,n]of midiNotes)if(n.index===index){midiSend([128+n.channel,n.note,0]);midiNotes.delete(id)}}$('#midiPanic').onclick=()=>{midiPanic();for(const [token]of [...pressed])if(String(token).startsWith('midi:'))release(token)};
let midiVoiceCounter=0;const coreAudioPlay=audio.play.bind(audio);audio.play=(p,index,options={})=>{const v=coreAudioPlay(p,index,options),config=midiConfig();if(!v||options.context&&options.context!==audio.ctx||options.fromMidi||!config.notesOut||!midiOut)return v;const note=Math.max(0,Math.min(127,Math.round(config.mode==='keys'?60+(options.pitch||0):36+(config.mode==='bank'?index%16:index)))),channel=config.outChannel-1,id=++midiVoiceCounter;const time=options.time??audio.ctx.currentTime;midiSend([144+channel,note,Math.round((options.velocity??1)*127)],time);midiNotes.set(id,{note,channel,index});const ended=v.src.onended;v.src.onended=()=>{const n=midiNotes.get(id);if(n){midiSend([128+n.channel,n.note,0]);midiNotes.delete(id)}ended?.()};return v};
function handleStudioMIDI(event){const data=event.data||[],status=data[0],config=midiConfig();if(config.input&&event.target?.id!==config.input)return;if(status>=248){if(!config.clockIn)return;const now=Number.isFinite(event.timeStamp)?event.timeStamp:performance.now();if(status===248){if(midiLastClock&&now>midiLastClock){const gap=now-midiLastClock;if(gap>5&&gap<100){midiIntervals.push(gap);if(midiIntervals.length>48)midiIntervals.shift();if(midiIntervals.length>=12){const sorted=midiIntervals.slice().sort((a,b)=>a-b),trim=sorted.slice(Math.floor(sorted.length*.2),Math.ceil(sorted.length*.8)),mean=trim.reduce((n,v)=>n+v,0)/trim.length;state.bpm=M.bound(60000/(24*mean),40,220,112);$('#tempoOpen').innerHTML=Math.round(state.bpm)+' <small>BPM</small>'}}}midiLastClock=now}else if(status===250||status===251){midiExternal=true;const resume=step;if(playing)stop();start().then(()=>{if(status===251)step=resume}).finally(()=>midiExternal=false)}else if(status===252){midiExternal=true;stop();midiExternal=false}return}const command=status&240,channel=(status&15)+1,note=data[1],velocity=data[2]||0;if(config.channel&&channel!==config.channel)return;const token='midi:'+(event.target?.id||'input')+':'+channel+':'+note;if(command===128||command===144&&velocity===0){release(token);return}if(command!==144||!Number.isInteger(note)||velocity<=0)return;let index,pitch=0;if(config.mode==='keys'){index=state.selected;pitch=Math.max(-24,Math.min(24,note-60))}else if(config.mode==='all'){if(note<36||note>99)return;index=note-36}else{if(note<36||note>51)return;index=state.bank*16+note-36}hit(index,token,pitch,{velocity:Math.max(1,Math.min(127,velocity))/127,fromMidi:true,gate:config.mode==='keys'})}
function midiTransportOut(status){if(!midiExternal&&midiConfig().clockOut)midiSend([status])}
const coreStart=start;start=async()=>{const wasPlaying=playing;await coreStart();if(!wasPlaying&&playing)midiTransportOut(250)};$('#play').onclick=start;
const coreSchedule=schedule;schedule=()=>{const from=nextTime,config=midiConfig();coreSchedule();if(!playing||!config.clockOut||config.clockIn||!midiOut)return;const tick=60/state.bpm/24;for(let t=from;t<nextTime-.00001;t+=tick)midiSend([248],t)};
window.addEventListener('blur',()=>{for(const [token]of [...pressed])if(String(token).startsWith('midi:'))release(token);midiPanic()});window.addEventListener('pagehide',midiPanic);refreshMidiUI();
